<script setup lang="ts">
import{onMounted,ref}from'vue'
import{countStocktake,createStocktake,createTransfer,getStocktakes,getTransfers,getVariants,getWarehouses,stocktakeAction,transferAction,type Stocktake,type Transfer,type Variant,type Warehouse}from'@/services/business'
const transfers=ref<Transfer[]>([]),stocktakes=ref<Stocktake[]>([]),warehouses=ref<Warehouse[]>([]),variants=ref<Variant[]>([])
const transferPage=ref(0),transferPages=ref(0),stocktakePage=ref(0),stocktakePages=ref(0)
const source=ref(''),destination=ref(''),variant=ref(''),quantity=ref(1),reason=ref('Điều chuyển hàng hóa'),stocktakeWarehouse=ref(''),stocktakeReason=ref('Kiểm kê định kỳ'),counts=ref<Record<string,number>>({}),error=ref('')
async function load(){const[transferResult,stocktakeResult,warehouseResult,variantResult]=await Promise.all([getTransfers(transferPage.value),getStocktakes(stocktakePage.value),getWarehouses(),getVariants()]);transfers.value=transferResult.items;transferPages.value=transferResult.totalPages;stocktakes.value=stocktakeResult.items;stocktakePages.value=stocktakeResult.totalPages;warehouses.value=warehouseResult;variants.value=variantResult}
async function moveTransferPage(value:number){transferPage.value=value;await load()}
async function moveStocktakePage(value:number){stocktakePage.value=value;await load()}
async function addTransfer(){try{await createTransfer({sourceWarehouseId:source.value,destinationWarehouseId:destination.value,reason:reason.value,items:[{variantId:variant.value,quantity:quantity.value}]});transferPage.value=0;await load()}catch{error.value='Không thể tạo điều chuyển.'}}
async function move(item:Transfer,action:'submit'|'approve'|'dispatch'|'receive'){try{await transferAction(item.id,action);await load()}catch{error.value='Không thể chuyển trạng thái điều chuyển.'}}
async function addStocktake(){try{await createStocktake({warehouseId:stocktakeWarehouse.value,reason:stocktakeReason.value});stocktakePage.value=0;await load()}catch{error.value='Không thể tạo đợt kiểm kê.'}}
async function saveCounts(item:Stocktake){try{await countStocktake(item.id,item.items.map(line=>({itemId:line.id,actualQuantity:counts.value[line.id]??line.systemQuantity})));await load()}catch{error.value='Không thể lưu số đếm.'}}
async function stockAction(item:Stocktake,action:'submit'|'approve'){try{await stocktakeAction(item.id,action);await load()}catch{error.value='Không thể chuyển trạng thái kiểm kê.'}}
onMounted(async()=>{try{await load()}catch{error.value='Không thể tải nghiệp vụ kho.'}})
</script>
<template><section class="p-6 lg:p-8"><p class="text-sm font-semibold text-cyan-700">Kiểm soát tồn kho</p><h2 class="text-3xl font-bold">Điều chuyển & kiểm kê</h2><p v-if="error" class="mt-5 rounded-lg bg-red-50 p-4 text-red-800">{{error}}</p><div class="mt-6 grid gap-6 xl:grid-cols-2"><form class="rounded-xl border bg-white p-5" @submit.prevent="addTransfer"><h3 class="font-bold">Tạo điều chuyển</h3><div class="mt-3 grid gap-3"><select v-model="source" required class="rounded border p-3"><option value="">Kho nguồn</option><option v-for="item in warehouses" :key="item.id" :value="item.id">{{item.name}}</option></select><select v-model="destination" required class="rounded border p-3"><option value="">Kho đích</option><option v-for="item in warehouses" :key="item.id" :value="item.id">{{item.name}}</option></select><select v-model="variant" required class="rounded border p-3"><option value="">SKU</option><option v-for="item in variants" :key="item.id" :value="item.id">{{item.sku}} · {{item.productName}}</option></select><input v-model.number="quantity" type="number" min="0.0001" step="0.0001" class="rounded border p-3"><input v-model="reason" required class="rounded border p-3"><button class="rounded bg-cyan-700 p-3 text-white">Tạo</button></div></form><form class="rounded-xl border bg-white p-5" @submit.prevent="addStocktake"><h3 class="font-bold">Tạo đợt kiểm kê</h3><div class="mt-3 grid gap-3"><select v-model="stocktakeWarehouse" required class="rounded border p-3"><option value="">Chọn kho</option><option v-for="item in warehouses" :key="item.id" :value="item.id">{{item.name}}</option></select><input v-model="stocktakeReason" required class="rounded border p-3"><button class="rounded bg-cyan-700 p-3 text-white">Bắt đầu kiểm kê</button></div></form></div>
<div class="mt-6 rounded-xl border bg-white p-5"><div class="flex justify-between"><h3 class="font-bold">Điều chuyển</h3><span class="text-sm">Trang {{transferPages?transferPage+1:0}} / {{transferPages}}</span></div><div class="mt-3 divide-y"><div v-for="item in transfers" :key="item.id" class="flex flex-wrap items-center justify-between gap-3 py-3"><span><b>{{item.transferNumber}}</b> · <StatusBadge :value="item.status" /> · {{item.items.map(line=>line.sku).join(', ')}}</span><button v-if="item.status==='DRAFT'" class="text-cyan-700" @click="move(item,'submit')">Gửi duyệt</button><button v-else-if="item.status==='PENDING_APPROVAL'" class="text-cyan-700" @click="move(item,'approve')">Duyệt</button><button v-else-if="item.status==='APPROVED'" class="text-cyan-700" @click="move(item,'dispatch')">Xuất kho</button><button v-else-if="item.status==='DISPATCHED'" class="text-cyan-700" @click="move(item,'receive')">Nhận kho</button></div><p v-if="!transfers.length" class="py-6 text-center text-slate-400">Chưa có điều chuyển.</p></div><div class="mt-3 flex justify-end gap-2"><button :disabled="transferPage===0" class="rounded border px-3 py-2 disabled:opacity-40" @click="moveTransferPage(transferPage-1)">Trước</button><button :disabled="transferPage+1>=transferPages" class="rounded border px-3 py-2 disabled:opacity-40" @click="moveTransferPage(transferPage+1)">Sau</button></div></div>
<div class="mt-6 rounded-xl border bg-white p-5"><div class="flex justify-between"><h3 class="font-bold">Kiểm kê</h3><span class="text-sm">Trang {{stocktakePages?stocktakePage+1:0}} / {{stocktakePages}}</span></div><div class="mt-3 divide-y"><div v-for="item in stocktakes" :key="item.id" class="py-4"><div class="flex justify-between"><b>{{item.stocktakeNumber}} · <StatusBadge :value="item.status" /></b><button v-if="item.status==='PENDING_APPROVAL'" class="text-cyan-700" @click="stockAction(item,'approve')">Duyệt chênh lệch</button></div><div v-if="item.status==='COUNTING'" class="mt-3 grid gap-2"><label v-for="line in item.items" :key="line.id" class="grid grid-cols-[1fr_8rem] items-center gap-2 text-sm"><span>{{line.sku}} · hệ thống {{line.systemQuantity}}</span><input v-model.number="counts[line.id]" :placeholder="String(line.systemQuantity)" type="number" min="0" step="0.0001" class="rounded border p-2"></label><div><button class="mr-4 text-cyan-700" @click="saveCounts(item)">Lưu số đếm</button><button class="text-cyan-700" @click="stockAction(item,'submit')">Gửi duyệt</button></div></div></div><p v-if="!stocktakes.length" class="py-6 text-center text-slate-400">Chưa có đợt kiểm kê.</p></div><div class="mt-3 flex justify-end gap-2"><button :disabled="stocktakePage===0" class="rounded border px-3 py-2 disabled:opacity-40" @click="moveStocktakePage(stocktakePage-1)">Trước</button><button :disabled="stocktakePage+1>=stocktakePages" class="rounded border px-3 py-2 disabled:opacity-40" @click="moveStocktakePage(stocktakePage+1)">Sau</button></div></div></section></template>
